BEGIN;
-- Preserve historical station primary keys and all booking/listing foreign keys.
ALTER TABLE "MrtStation" ADD COLUMN "canonicalId" TEXT, ADD COLUMN "nameEn" TEXT, ADD COLUMN "nameZh" TEXT,
ADD COLUMN "lineCodes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "operatorIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
ADD COLUMN "systemIds" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "operational" BOOLEAN NOT NULL DEFAULT false;
CREATE UNIQUE INDEX "MrtStation_canonicalId_key" ON "MrtStation"("canonicalId");
UPDATE "MrtStation" SET "canonicalId"='taipei-main',"nameEn"='Taipei Main Station',"nameZh"='台北車站',"lineCodes"=ARRAY['R10','BL12']::TEXT[],"operatorIds"=ARRAY['TRTC']::TEXT[],"systemIds"=ARRAY['taipei-mrt']::TEXT[],"operational"=true WHERE "code"='TPE';
UPDATE "MrtStation" SET "canonicalId"='zhongshan',"nameEn"='Zhongshan',"nameZh"='中山',"lineCodes"=ARRAY['R11','G14']::TEXT[],"operatorIds"=ARRAY['TRTC']::TEXT[],"systemIds"=ARRAY['taipei-mrt']::TEXT[],"operational"=true WHERE "code"='ZSH';
UPDATE "MrtStation" SET "canonicalId"='taipei-mrt:station:057',"nameEn"='Jiantan',"nameZh"='劍潭',"lineCodes"=ARRAY['R15']::TEXT[],"operatorIds"=ARRAY['TRTC']::TEXT[],"systemIds"=ARRAY['taipei-mrt']::TEXT[],"operational"=true WHERE "code"='JNT';
UPDATE "MrtStation" SET "canonicalId"='ximen',"nameEn"='Ximen',"nameZh"='西門',"lineCodes"=ARRAY['G12','BL11']::TEXT[],"operatorIds"=ARRAY['TRTC']::TEXT[],"systemIds"=ARRAY['taipei-mrt']::TEXT[],"operational"=true WHERE "code"='XIM';
UPDATE "MrtStation" SET "canonicalId"='taipei-mrt:station:111',"nameEn"='Songshan',"nameZh"='松山',"lineCodes"=ARRAY['G19']::TEXT[],"operatorIds"=ARRAY['TRTC']::TEXT[],"systemIds"=ARRAY['taipei-mrt']::TEXT[],"operational"=true WHERE "code"='SSH';
COMMIT;
